import { AnimatePresence, motion, PanInfo, useMotionValue, animate } from "framer-motion";
import { useCallback, useEffect, useState } from "react";
import styles from "./light-box.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { Modal } from "@/core/components/primitives/modal/modal";
import { multipleClassNames } from "../../../helpers";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import { useTranslation } from "react-i18next";

export type LightboxItemTypeImage = {
  type: "image";
  url: string;
};

export type LightboxItemTypeYouTube = {
  type: "youtube";
  youtubeUrl: string;
  url?: string;
  urlArgs?: string;
  autoPlay?: boolean;
};

export type LightboxItem = LightboxItemTypeImage | LightboxItemTypeYouTube;

export type LightboxProps = {
  /** Array of items to display in the lightbox */
  items: LightboxItem[];
  /** Whether the lightbox is open */
  isOpen: boolean;
  /** Callback when the lightbox should close */
  onClose: () => void;
  /** Initial index to show when opening (defaults to 0) */
  initialIndex?: number;
};

/** Minimum swipe velocity to trigger navigation */
const VELOCITY_THRESHOLD = 500;

export const Lightbox = ({ items, isOpen, onClose, initialIndex = 0 }: LightboxProps) => {
  const [isExiting, setIsExiting] = useState(false);
  const [currentPage, setCurrentPage] = useState(initialIndex);

  const { t } = useTranslation();

  const [listRef, setListRef] = useState<HTMLDivElement | null>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  const x = useMotionValue(0);

  const totalPages = items.length;
  const canNavigatePrev = currentPage > 0;
  const canNavigateNext = currentPage < totalPages - 1;

  // Reset to initialIndex when lightbox opens
  useEffect(() => {
    if (isOpen) {
      const validIndex = Math.min(Math.max(0, initialIndex), items.length - 1);
      setCurrentPage(validIndex);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, initialIndex]);

  // use ResizeObserver to track width of listRef, since it can change size while images/videos load
  useEffect(() => {
    if (!listRef) return undefined;

    const obs = new ResizeObserver(() => setContainerWidth(listRef.offsetWidth || 1));
    obs.observe(listRef);
    return () => obs.disconnect();
  }, [listRef]);

  // Animate carousel position when currentPage changes
  useEffect(() => {
    const targetX = -currentPage * containerWidth;

    animate(x, targetX, {
      type: "spring",
      stiffness: 300,
      damping: 30,
    });
  }, [containerWidth, currentPage, x]);

  // Trigger exit animation, then call onClose
  const handleClose = useCallback(() => {
    setIsExiting(true);
  }, []);

  // Handle animation complete
  const handleAnimationComplete = useCallback(() => {
    if (isExiting) {
      setIsExiting(false);
      onClose();
    }
  }, [isExiting, onClose]);

  // Navigation handlers
  const navigateNext = useCallback(() => {
    if (canNavigateNext) {
      setCurrentPage((prev) => prev + 1);
    }
  }, [canNavigateNext]);
  const navigatePrev = useCallback(() => {
    if (canNavigatePrev) {
      setCurrentPage((prev) => prev - 1);
    }
  }, [canNavigatePrev]);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return void 0;

    const handleKeyDown = (e: KeyboardEvent) => {
      switch (e.key) {
        case "Escape":
          handleClose();
          break;
        case "ArrowLeft":
          navigatePrev();
          break;
        case "ArrowRight":
          navigateNext();
          break;
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, handleClose, navigateNext, navigatePrev]);

  // Handle swipe gestures on the lightbox
  const handleDragEnd = useCallback(
    (_e: unknown, { offset, velocity }: PanInfo) => {
      let newIndex = currentPage;

      // If fast swipe, use velocity
      if (Math.abs(velocity.x) > VELOCITY_THRESHOLD) {
        newIndex = velocity.x > 0 ? currentPage - 1 : currentPage + 1;
      }
      // Otherwise use offset threshold (30% of container width)
      else if (Math.abs(offset.x) > containerWidth * 0.3) {
        newIndex = offset.x > 0 ? currentPage - 1 : currentPage + 1;
      }

      // Clamp index
      newIndex = Math.max(0, Math.min(items.length - 1, newIndex));

      if (newIndex !== currentPage) {
        setCurrentPage(newIndex);
      }
    },
    [containerWidth, currentPage, items.length],
  );

  return (
    <AnimatePresence>
      {isOpen && (
        <Modal
          isOpen={isOpen}
          onClose={handleClose}
          disableScrollClassName="overflow-hidden"
          portalId={MODAL_PORTAL_ID}
          className={styles.modal}
          innerClassName={styles.modalInner}
        >
          <PrimaryButton
            iconCenterNew="close"
            iconSize="xxl"
            className={styles.closeButton}
            onClick={handleClose}
            ariaLabel={t("close")}
          />
          <motion.div
            className={styles.lightbox}
            initial={{ opacity: 0 }}
            animate={{ opacity: isExiting ? 0 : 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            onAnimationComplete={handleAnimationComplete}
          >
            {/* Content wrapper */}
            <div className={styles.contentWrapper}>
              <div className={styles.innerWrapper}>
                {/* Carousel list */}
                <div ref={setListRef} className={styles.listWrapper}>
                  <motion.div
                    className={styles.list}
                    drag="x"
                    dragElastic={0.2}
                    dragMomentum={false}
                    onDragEnd={handleDragEnd}
                    style={{ x }}
                  >
                    {items.map((item, index) => (
                      <div
                        key={index}
                        className={multipleClassNames(styles.listItem)}
                        style={{ flexShrink: 0, width: "100%" }}
                      >
                        {item.type === "image" && item.url && (
                          <img className={styles.image} src={item.url} alt="" loading="lazy" />
                        )}

                        {item.type === "youtube" && item.youtubeUrl && (
                          <div className={styles.youtubeWrapper}>
                            <iframe
                              src={`${item.youtubeUrl}?enablejsapi=1${item.autoPlay ? "&autoplay=1&mute=1" : ""}${
                                item.urlArgs ?? ""
                              }`}
                              className={styles.youtubeIframe}
                              allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
                              allowFullScreen
                              title="YouTube video"
                              referrerPolicy="strict-origin-when-cross-origin"
                            />
                          </div>
                        )}
                      </div>
                    ))}
                  </motion.div>
                </div>
              </div>

              {/* Page indicator dots */}
              {totalPages > 1 && (
                <>
                  <PrimaryButton
                    iconCenterNew="chevron-left"
                    iconSize="xl"
                    className={`${styles.navButton} ${styles.navPrev}`}
                    onClick={navigatePrev}
                    isDisabled={!canNavigatePrev}
                    ariaLabel={t("previous")}
                  />
                  <div className={styles.dotsWrapper}>
                    {items.map((_, index) => (
                      <button
                        key={index}
                        className={styles.dot}
                        data-active={index === currentPage}
                        onClick={() => {
                          setCurrentPage(index);
                        }}
                        aria-label={`${t("show")} ${index + 1}`}
                      />
                    ))}
                  </div>
                  <PrimaryButton
                    iconCenterNew="chevron-right"
                    iconSize="xl"
                    className={multipleClassNames(styles.navButton, styles.navNext)}
                    onClick={navigateNext}
                    isDisabled={!canNavigateNext}
                    ariaLabel={t("next")}
                  />
                </>
              )}
            </div>
          </motion.div>
        </Modal>
      )}
    </AnimatePresence>
  );
};
